// Split the places[] array from the Text Search response into individual n8n items
const places = $input.first().json.places || [];
return places.map(p => ({
  json: {
    place_id: p.id,
    name: p.displayName ? p.displayName.text : '',
    website: p.websiteUri || null,
    rating: p.rating || null,
    review_count: p.userRatingCount || 0,
    phone: p.nationalPhoneNumber || null,
    address: p.formattedAddress || null
  }
}));

const original = $('5. Has Website?').item.json;
const html = (typeof $json.data === 'string') ? $json.data : '';
const textOnly = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

let schemaTypes = [];
const ldMatches = [...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
for (const m of ldMatches) {
  try {
    const parsed = JSON.parse(m[1].trim());
    const items = Array.isArray(parsed) ? parsed : [parsed];
    for (const it of items) { if (it['@type']) schemaTypes.push(it['@type']); }
  } catch (e) { /* malformed JSON-LD, skip */ }
}

return [{
  json: {
    ...original,
    page_text: textOnly.slice(0, 6000),
    text_length: textOnly.length,
    fetch_failed: !html,
    has_schema_markup: schemaTypes.length > 0,
    schema_types: schemaTypes
  }
}];

const original = $('7. Parse HTML + Detect Schema').item.json;
const ps = $json;
const perfScore = ps && ps.lighthouseResult && ps.lighthouseResult.categories && ps.lighthouseResult.categories.performance
  ? Math.round(ps.lighthouseResult.categories.performance.score * 100)
  : null;
const audits = (ps && ps.lighthouseResult && ps.lighthouseResult.audits) || {};
const lcp = audits['largest-contentful-paint'] ? audits['largest-contentful-paint'].displayValue : null;
const cls = audits['cumulative-layout-shift'] ? audits['cumulative-layout-shift'].displayValue : null;

return [{
  json: {
    ...original,
    pagespeed_score: perfScore,
    lcp,
    cls
  }
}];

const original = $('9. Recombine: PageSpeed Result').item.json;
const robotsTxt = (typeof $json.data === 'string') ? $json.data : '';
const aiBots = ['GPTBot', 'ClaudeBot', 'PerplexityBot', 'OAI-SearchBot', 'Google-Extended', 'Applebot'];
let blockedBots = [];
if (robotsTxt) {
  const lines = robotsTxt.split('\n');
  let currentAgent = null;
  for (const raw of lines) {
    const line = raw.trim();
    const uaMatch = line.match(/^User-agent:\s*(.+)$/i);
    if (uaMatch) currentAgent = uaMatch[1].trim();
    const disallowMatch = line.match(/^Disallow:\s*\/?\s*$/i);
    if (disallowMatch && currentAgent && aiBots.some(b => b.toLowerCase() === currentAgent.toLowerCase())) {
      blockedBots.push(currentAgent);
    }
  }
}
return [{
  json: {
    ...original,
    ai_crawlers_blocked: blockedBots,
    crawler_access_ok: blockedBots.length === 0
  }
}];

const original = $('11. Recombine: robots.txt Result').item.json;
const hasLlmsTxt = typeof $json.data === 'string' && $json.data.length > 0 && !$json.error;

const pageSpeedComponent = (original.pagespeed_score !== null && original.pagespeed_score !== undefined ? original.pagespeed_score : 30) * 0.5;
const crawlerComponent = (original.crawler_access_ok ? 100 : 0) * 0.2;
const schemaComponent = (original.has_schema_markup ? 100 : 0) * 0.2;
const llmsTxtComponent = (hasLlmsTxt ? 100 : 0) * 0.1;
const technical_score = Math.round(pageSpeedComponent + crawlerComponent + schemaComponent + llmsTxtComponent);

return [{
  json: {
    ...original,
    has_llms_txt: hasLlmsTxt,
    technical_score
  }
}];

