  try {
    const parsed = JSON.parse(m[1].trim());
    const items = Array.isArray(parsed) ? parsed : [parsed];
    for (const it of items) {
      if (it['@type']) schemaTypes.push(it['@type']);
      const t = Array.isArray(it['@type']) ? it['@type'] : [it['@type']];
      if (!schemaName && it.name && t.some(x => /organization|localbusiness/i.test(String(x)))) {
        schemaName = it.name;
      }
    }
  } catch (e) { /* malformed JSON-LD, skip */ }
}

// og:site_name meta tag
const ogMatch = html.match(/<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i);
const ogName = ogMatch ? ogMatch[1].trim() : null;

// <title> tag, trimmed at common separators
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
let titleName = null;
if (titleMatch) {
  titleName = titleMatch[1].split(/[|\u2013\u2014-]/)[0].trim();
}

// Domain fallback
let domainName = null;
try {
  const host = new URL(original.website).hostname.replace(/^www\./, '');
  domainName = host.split('.')[0].replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
} catch (e) { /* invalid URL, ignore */ }

const inferred_name = original.name_override || schemaName || ogName || titleName || domainName || '';

return [{
  json: {
    ...original,
    inferred_name,
    name_source: original.name_override ? 'user_override' : (schemaName ? 'schema_org' : (ogName ? 'og_site_name' : (titleName ? 'title_tag' : 'domain_fallback'))),
