const original = $('B11. Compute Technical Score').item.json;
let parsed = { design_score: null, copy_score: null, verdict: 'unknown', pitch: '' };
try {
  const text = $json.content && $json.content[0] && $json.content[0].text ? $json.content[0].text : '{}';
  const cleaned = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) { /* Claude didn't return clean JSON, keep defaults */ }

return [{
  json: {
    place_id: original.place_id,
    name: original.matched_name || original.inferred_name,
    website: original.website,
    rating: original.rating,
    review_count: original.review_count,
    phone: original.phone,
    address: original.address,
    lead_type: 'direct_website_check',
    google_listing_matched: original.google_listing_matched,
    name_source: original.name_source,
    technical_score: original.technical_score,
    pagespeed_score: original.pagespeed_score,
    lcp: original.lcp,
    cls: original.cls,
    ai_crawlers_blocked: original.ai_crawlers_blocked,
    crawler_access_ok: original.crawler_access_ok,
    has_schema_markup: original.has_schema_markup,
    has_llms_txt: original.has_llms_txt,
    design_score: parsed.design_score,
    copy_score: parsed.copy_score,
    verdict: parsed.verdict,
    pitch: parsed.pitch
  }
}];

const items = $input.all().map(i => i.json);
const summary = {
  success: true,
  count: items.length,
  leads: items.map(i => ({
    name: i.name || null,
    website: i.website || null,
    lead_type: i.lead_type || null,
    technical_score: i.technical_score ?? null,
    verdict: i.verdict || null,
    review_count: i.review_count ?? null,
    pitch: i.pitch || null
  }))
};
return [{ json: summary }];

// At this point every business in THIS search batch has already been technically scored.
// Compute real, verifiable stats across the batch so the AI pitch can cite actual numbers
// instead of inventing a generic "competitors are already doing this" claim.
const items = $input.all();
const scored = items.filter(i => i.json.website); // only businesses that had a website to score
const batch_size = scored.length;
const llms_txt_count = scored.filter(i => i.json.has_llms_txt).length;
const crawler_blocked_count = scored.filter(i => i.json.crawler_access_ok === false).length;
const avg_pagespeed = scored.length
  ? Math.round(scored.reduce((sum, i) => sum + (i.json.pagespeed_score ?? 0), 0) / scored.length)
  : null;

return items.map(i => ({
  json: {
    ...i.json,
    batch_size,
    batch_llms_txt_count: llms_txt_count,
    batch_crawler_blocked_count: crawler_blocked_count,
    batch_avg_pagespeed: avg_pagespeed
  }
}));
